def solve(inputs: dict) -> float:
    # Linear congruential generator: X = (a * X + c) mod m
    # Applied for n rounds

    x = inputs.get('initial_x', 250)
    a = inputs.get('a', 500)
    c = inputs.get('c', 2700)
    m = inputs.get('m', 45300)
    rounds = inputs.get('rounds', 6)

    for _ in range(rounds):
        x = (a * x + c) % m

    return float(x)
"}
